Arguments: {"title":"Extract clean transcript from Video 1","cwd":null,"code":"const tabId = 725789690;

const captions = await browserjs(tabId, async () => {
  const pr = window.ytInitialPlayerResponse;
  const track = pr?.captions?.playerCaptionsTracklistRenderer?.captionTracks?.[0];
  if (!track) return { error: "No track found" };
  const resp = await fetch(track.baseUrl);
  const text = await resp.text();
  // Simple regex to extract text contents without DOMParser
  const matches = text.match(/<text[^>]*>([\s\S]*?)<\/text>/g) || [];
  const clean = matches.map(m => m.replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'").replace(/&quot;/g, '"')).join(' ');
  return {
    title: pr.videoDetails?.title,
    author: pr.videoDetails?.author,
    cleanText: clean
  };
});

console.log("Video 1 Title:", captions.title);
console.log("Video 1 Author:", captions.author);
